	<div
		class="main-frame-clip-boundary"
		:class="{ 'is-open': isOpen }"
	>
		<div
			class="main-frame"
			:class="{ 'is-open': isOpen }"
		>
			<div class="tl"></div>
			<div class="bl"></div>
			<div class="tr"></div>
			<div class="br"></div>
		</div>
	</div>

</template>
<style lang="scss" scoped>

	.main-frame-clip-boundary {

		// don't interfere with pointer events on the content, but still be above the canvas
